--
-- Table structure for table `customer_debt`
--

DROP TABLE IF EXISTS `customer_debt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customer_debt` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int NOT NULL,
  `order_id` int NOT NULL,
  `category_id` int DEFAULT NULL,
  `qty` decimal(18,2) DEFAULT NULL,
  `unit_price` decimal(18,2) DEFAULT NULL,
  `actual_price` decimal(18,2) DEFAULT NULL,
  `total_amount` decimal(12,2) NOT NULL COMMENT 'Total amount of the order',
  `paid_amount` decimal(12,2) DEFAULT '0.00' COMMENT 'Amount already paid',
  `due_amount` decimal(12,2) GENERATED ALWAYS AS ((`total_amount` - `paid_amount`)) STORED,
  `due_date` date DEFAULT NULL COMMENT 'Expected payment date',
  `last_payment_date` datetime DEFAULT NULL COMMENT 'Date of last payment',
  `payment_status` enum('Paid','Partial','Unpaid') GENERATED ALWAYS AS ((case when ((`total_amount` - `paid_amount`) = 0) then _utf8mb4'Paid' when (`paid_amount` > 0) then _utf8mb4'Partial' else _utf8mb4'Unpaid' end)) STORED,
  `notes` text COMMENT 'Any special notes about this debt',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
